import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts a valid list_sessions frame with optional limits and cursors', () => {
    expect(validateMessage({type: 'list_sessions'})).toEqual({
      valid: true,
      data: {type: 'list_sessions'}
    });

    expect(validateMessage({
      type: 'list_sessions',
      limit: 50,
      before: {sessionId: 's1', updatedAt: '2025-01-01T00:00:00.000Z'},
      userId: 'ignored'
    })).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 50,
        before: {sessionId: 's1', updatedAt: '2025-01-01T00:00:00.000Z'}
      }
    });
  });

  it('rejects list_sessions with invalid limits', () => {
    expect(validateMessage({type: 'list_sessions', limit: '10'})).toEqual({valid: false, error: 'limit must be a non-negative integer'});
    expect(validateMessage({type: 'list_sessions', limit: 1.5})).toEqual({valid: false, error: 'limit must be a non-negative integer'});
    expect(validateMessage({type: 'list_sessions', limit: -1})).toEqual({valid: false, error: 'limit must be a non-negative integer'});
  });

  it('rejects list_sessions with invalid before cursors', () => {
    expect(validateMessage({type: 'list_sessions', before: {sessionId: 's1'}})).toEqual({valid: false, error: 'before must have string sessionId and finite date updatedAt'});
    expect(validateMessage({type: 'list_sessions', before: {updatedAt: '2025-01-01T00:00:00.000Z'}})).toEqual({valid: false, error: 'before must have string sessionId and finite date updatedAt'});
    expect(validateMessage({type: 'list_sessions', before: {sessionId: '', updatedAt: '2025-01-01T00:00:00.000Z'}})).toEqual({valid: false, error: 'sessionId must be 1-128 characters'});
    expect(validateMessage({type: 'list_sessions', before: {sessionId: 's1', updatedAt: 'not a date'}})).toEqual({valid: false, error: 'before must have string sessionId and finite date updatedAt'});
  });
});
EOF
